public static boolean isFlightEnabled(SysFlightName _flightName)
{
    boolean isFlightEnabled;

    isFlightEnabled = next isFlightEnabled(_flightName);

    if (!isFlightEnabled
     && _flightName == 'WHSConfirmAndTransferInventoryAtPackingStationToggle')
    {
        isFlightEnabled = true;
    }

    return isFlightEnabled;
}
